effect.shader:
// uIntensidade, uGlow e uDetalhe vêm dos <params> (o prelúdio declara).

// Quantos níveis de pirâmide a imagem está acima ou abaixo de 1080 (o lado menor,
// em pixels da camada): o ajuste foi feito em 1080p.
float acDeltaNivel() {
    vec2 tam = vec2(textureSize(inputImg, 0)) / max(acEscalaDePixel, 0.05);
    return log2(max(min(tam.x, tam.y), 16.0) / 1080.0);
}

vec3 paraLuz(vec3 c) {
    vec3 alto = pow(max(c + 0.055, 0.0) / 1.055, vec3(2.4));
    return mix(c / 12.92, alto, step(vec3(0.04045), c));
}

vec3 paraTela(vec3 l) {
    vec3 s = max(l, 0.0);
    return mix(s * 12.92, 1.055 * pow(s, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), s));
}

// A LUT 33³ do atlas: 33 ladrilhos 33×33 lado a lado (x = b·33 + r, y = linha0 + g).
vec3 lut(vec3 c, float linha0) {
    vec2 tam = vec2(textureSize(atlas, 0));
    vec3 p = clamp(c, 0.0, 1.0) * 32.0;
    float b0 = floor(p.b);
    float b1 = min(b0 + 1.0, 32.0);
    float t = p.b - b0;
    float v = (linha0 + p.g + 0.5) / tam.y;
    vec3 a = texture(atlas, vec2((b0 * 33.0 + p.r + 0.5) / tam.x, v)).rgb;
    vec3 d = texture(atlas, vec2((b1 * 33.0 + p.r + 0.5) / tam.x, v)).rgb;
    return mix(a, d, t);
}

// A descida da pirâmide: tenda 4×4 (como o Deep Glow).
vec3 descer(sampler2D origem) {
    ivec2 tamI = textureSize(origem, 0);
    vec2 p = acScreenNorm * vec2(tamI);
    vec2 t0 = floor(p) - 2.0;
    vec3 soma = vec3(0.0);
    float pesos = 0.0;
    for (int j = 0; j < 4; j++) {
        for (int i = 0; i < 4; i++) {
            vec2 t = t0 + vec2(float(i), float(j));
            vec2 w = max(2.0 - abs(t + 0.5 - p), 0.0);
            float peso = w.x * w.y;
            soma += texelFetch(origem, clamp(ivec2(t), ivec2(0), tamI - 1), 0).rgb * peso;
            pesos += peso;
        }
    }
    return soma / max(pesos, 0.0001);
}

// O glow guarda LUZ (linear) em 8 bits com raiz — a mesma de Deep Glow — e com ruído.
float ruidoDoPixel() {
    return fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5;
}
vec4 guardar(vec3 luz) { return vec4(sqrt(max(luz, 0.0)) + ruidoDoPixel() / 255.0, 1.0); }
vec3 abrir(vec3 g) { return g * g; }

vec3 cortar(vec3 c, float limiar, float joelho) {
    float vista = dot(c, vec3(0.2126, 0.7152, 0.0722));
    float t = clamp((vista - limiar) / max(joelho, 0.0001), 0.0, 1.0);
    return paraLuz(c) * (t * t * (3.0 - 2.0 * t));
}

vec4 descerComCorte(sampler2D origem, float limiar, float joelho) {
    ivec2 tamI = textureSize(origem, 0);
    vec2 p = acScreenNorm * vec2(tamI);
    vec2 t0 = floor(p) - 2.0;
    vec3 soma = vec3(0.0);
    float pesos = 0.0;
    for (int j = 0; j < 4; j++) {
        for (int i = 0; i < 4; i++) {
            vec2 t = t0 + vec2(float(i), float(j));
            vec2 w = max(2.0 - abs(t + 0.5 - p), 0.0);
            float peso = w.x * w.y;
            soma += cortar(texelFetch(origem, clamp(ivec2(t), ivec2(0), tamI - 1), 0).rgb, limiar, joelho) * peso;
            pesos += peso;
        }
    }
    return guardar(soma / max(pesos, 0.0001));
}

vec4 descerLuz(sampler2D origem) {
    ivec2 tamI = textureSize(origem, 0);
    vec2 p = acScreenNorm * vec2(tamI);
    vec2 t0 = floor(p) - 2.0;
    vec3 soma = vec3(0.0);
    float pesos = 0.0;
    for (int j = 0; j < 4; j++) {
        for (int i = 0; i < 4; i++) {
            vec2 t = t0 + vec2(float(i), float(j));
            vec2 w = max(2.0 - abs(t + 0.5 - p), 0.0);
            float peso = w.x * w.y;
            soma += abrir(texelFetch(origem, clamp(ivec2(t), ivec2(0), tamI - 1), 0).rgb) * peso;
            pesos += peso;
        }
    }
    return guardar(soma / max(pesos, 0.0001));
}

// A subida: B-spline cúbica em quatro leituras (o `lerLiso` do Deep Glow).
vec3 lerLiso(sampler2D t, vec2 uv) {
    vec2 tam = vec2(textureSize(t, 0));
    vec2 p = uv * tam - 0.5;
    vec2 i = floor(p);
    vec2 f = p - i;
    vec2 f2 = f * f;
    vec2 f3 = f2 * f;
    vec2 w0 = (1.0 - 3.0 * f + 3.0 * f2 - f3) / 6.0;
    vec2 w1 = (4.0 - 6.0 * f2 + 3.0 * f3) / 6.0;
    vec2 w2 = (1.0 + 3.0 * f + 3.0 * f2 - 3.0 * f3) / 6.0;
    vec2 w3 = f3 / 6.0;
    vec2 g0 = w0 + w1;
    vec2 g1 = w2 + w3;
    vec2 a = (i - 1.0 + w1 / max(g0, 0.0001) + 0.5) / tam;
    vec2 b = (i + 1.0 + w3 / max(g1, 0.0001) + 0.5) / tam;
    return texture(t, vec2(a.x, a.y)).rgb * g0.x * g0.y
         + texture(t, vec2(b.x, a.y)).rgb * g1.x * g0.y
         + texture(t, vec2(a.x, b.y)).rgb * g0.x * g1.y
         + texture(t, vec2(b.x, b.y)).rgb * g1.x * g1.y;
}


vec3 nivelX2(float n, vec2 uv) {
    n = clamp(n, 1.0, 8.0);
    float a = floor(n);
    float t = n - a;
    vec3 r = vec3(0.0);
    if (a == 1.0) r = lerLiso(x2_1, uv) * (1.0 - t) + lerLiso(x2_2, uv) * t;
    if (a == 2.0) r = lerLiso(x2_2, uv) * (1.0 - t) + lerLiso(x2_3, uv) * t;
    if (a == 3.0) r = lerLiso(x2_3, uv) * (1.0 - t) + lerLiso(x2_4, uv) * t;
    if (a == 4.0) r = lerLiso(x2_4, uv) * (1.0 - t) + lerLiso(x2_5, uv) * t;
    if (a == 5.0) r = lerLiso(x2_5, uv) * (1.0 - t) + lerLiso(x2_6, uv) * t;
    if (a == 6.0) r = lerLiso(x2_6, uv) * (1.0 - t) + lerLiso(x2_7, uv) * t;
    if (a == 7.0) r = lerLiso(x2_7, uv) * (1.0 - t) + lerLiso(x2_8, uv) * t;
    if (a == 8.0) r = lerLiso(x2_8, uv) * (1.0 - t);
    return r;
}

vec3 nivelF2_luz(float n, vec2 uv) {
    n = clamp(n, 1.0, 8.0);
    float a = floor(n);
    float t = n - a;
    vec3 r = vec3(0.0);
    if (a == 1.0) r = abrir(lerLiso(f2_1, uv)) * (1.0 - t) + abrir(lerLiso(f2_2, uv)) * t;
    if (a == 2.0) r = abrir(lerLiso(f2_2, uv)) * (1.0 - t) + abrir(lerLiso(f2_3, uv)) * t;
    if (a == 3.0) r = abrir(lerLiso(f2_3, uv)) * (1.0 - t) + abrir(lerLiso(f2_4, uv)) * t;
    if (a == 4.0) r = abrir(lerLiso(f2_4, uv)) * (1.0 - t) + abrir(lerLiso(f2_5, uv)) * t;
    if (a == 5.0) r = abrir(lerLiso(f2_5, uv)) * (1.0 - t) + abrir(lerLiso(f2_6, uv)) * t;
    if (a == 6.0) r = abrir(lerLiso(f2_6, uv)) * (1.0 - t) + abrir(lerLiso(f2_7, uv)) * t;
    if (a == 7.0) r = abrir(lerLiso(f2_7, uv)) * (1.0 - t) + abrir(lerLiso(f2_8, uv)) * t;
    if (a == 8.0) r = abrir(lerLiso(f2_8, uv)) * (1.0 - t);
    return r;
}

vec3 popDe2(vec2 uv) {
    vec3 x = texture(x2, uv).rgb;
    vec3 g = x;
    g = g + (nivelX2(float(2) + 1.0 + acDeltaNivel(), uv) - g) * texture(atlas, vec2((0.0 + clamp(uv.x * 16.0, 0.5, 16.0 - 0.5)) / 1089.0, (69.0 + clamp(uv.y * 9.0, 0.5, 9.0 - 0.5)) / 147.0)).rgb.r * uDetalhe;
    vec3 n0 = nivelX2(0.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n1 = nivelX2(1.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n2 = nivelX2(2.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n3 = nivelX2(3.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n4 = nivelX2(4.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n5 = nivelX2(5.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n6 = nivelX2(6.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n7 = nivelX2(7.0 + 1.0 + acDeltaNivel(), uv);
    g = g + uDetalhe * (-0.066371 * (g - n0) + -0.707379 * n0 * (1.0 - g) + -0.051584 * (g - n1) + 0.779939 * n1 * (1.0 - g) + 0.230506 * (g - n2) + -0.033647 * n2 * (1.0 - g) + -0.008544 * (g - n3) + -0.048467 * n3 * (1.0 - g) + 0.020995 * (g - n4) + 0.010050 * n4 * (1.0 - g) + 0.006659 * (g - n5) + 0.022586 * n5 * (1.0 - g) + -0.018036 * (g - n6) + -0.025731 * n6 * (1.0 - g) + -0.000850 * (g - n7) + -0.005582 * n7 * (1.0 - g));
    return clamp(g, 0.0, 1.0);
}

vec3 saida2(vec2 uv) {
    vec3 lin = paraLuz(texture(g2, uv).rgb);
    vec3 luz = uGlow * (vec3(0.020912, 0.034098, 0.000000) * nivelF2_luz(1.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.035133, 0.015803, 0.034629) * nivelF2_luz(2.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.002209, 0.000000) * nivelF2_luz(3.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.000000, 0.007047) * nivelF2_luz(4.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.000000, 0.002600) * nivelF2_luz(5.0 + 1.0 + acDeltaNivel(), uv));
    lin += luz * (1.0 - lin);
    return paraTela(lin);
}

vec3 nivelX3(float n, vec2 uv) {
    n = clamp(n, 1.0, 8.0);
    float a = floor(n);
    float t = n - a;
    vec3 r = vec3(0.0);
    if (a == 1.0) r = lerLiso(x3_1, uv) * (1.0 - t) + lerLiso(x3_2, uv) * t;
    if (a == 2.0) r = lerLiso(x3_2, uv) * (1.0 - t) + lerLiso(x3_3, uv) * t;
    if (a == 3.0) r = lerLiso(x3_3, uv) * (1.0 - t) + lerLiso(x3_4, uv) * t;
    if (a == 4.0) r = lerLiso(x3_4, uv) * (1.0 - t) + lerLiso(x3_5, uv) * t;
    if (a == 5.0) r = lerLiso(x3_5, uv) * (1.0 - t) + lerLiso(x3_6, uv) * t;
    if (a == 6.0) r = lerLiso(x3_6, uv) * (1.0 - t) + lerLiso(x3_7, uv) * t;
    if (a == 7.0) r = lerLiso(x3_7, uv) * (1.0 - t) + lerLiso(x3_8, uv) * t;
    if (a == 8.0) r = lerLiso(x3_8, uv) * (1.0 - t);
    return r;
}

vec3 nivelF3_luz(float n, vec2 uv) {
    n = clamp(n, 1.0, 8.0);
    float a = floor(n);
    float t = n - a;
    vec3 r = vec3(0.0);
    if (a == 1.0) r = abrir(lerLiso(f3_1, uv)) * (1.0 - t) + abrir(lerLiso(f3_2, uv)) * t;
    if (a == 2.0) r = abrir(lerLiso(f3_2, uv)) * (1.0 - t) + abrir(lerLiso(f3_3, uv)) * t;
    if (a == 3.0) r = abrir(lerLiso(f3_3, uv)) * (1.0 - t) + abrir(lerLiso(f3_4, uv)) * t;
    if (a == 4.0) r = abrir(lerLiso(f3_4, uv)) * (1.0 - t) + abrir(lerLiso(f3_5, uv)) * t;
    if (a == 5.0) r = abrir(lerLiso(f3_5, uv)) * (1.0 - t) + abrir(lerLiso(f3_6, uv)) * t;
    if (a == 6.0) r = abrir(lerLiso(f3_6, uv)) * (1.0 - t) + abrir(lerLiso(f3_7, uv)) * t;
    if (a == 7.0) r = abrir(lerLiso(f3_7, uv)) * (1.0 - t) + abrir(lerLiso(f3_8, uv)) * t;
    if (a == 8.0) r = abrir(lerLiso(f3_8, uv)) * (1.0 - t);
    return r;
}

vec3 popDe3(vec2 uv) {
    vec3 x = texture(x3, uv).rgb;
    vec3 g = x;
    vec3 n0 = nivelX3(0.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n1 = nivelX3(1.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n2 = nivelX3(2.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n3 = nivelX3(3.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n4 = nivelX3(4.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n5 = nivelX3(5.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n6 = nivelX3(6.0 + 1.0 + acDeltaNivel(), uv);
    vec3 n7 = nivelX3(7.0 + 1.0 + acDeltaNivel(), uv);
    g = g + uDetalhe * (0.013591 * n0 * (1.0 - g) + -0.081736 * (g - n1) + -0.005735 * n1 * (1.0 - g) + -0.034226 * (g - n2) + -0.010469 * n2 * (1.0 - g) + 0.061906 * (g - n3) + 0.020427 * n3 * (1.0 - g) + -0.039975 * (g - n4) + -0.020920 * n4 * (1.0 - g) + 0.017298 * (g - n5) + 0.007431 * n5 * (1.0 - g) + -0.008206 * (g - n6) + -0.009628 * n6 * (1.0 - g) + 0.001395 * (g - n7) + 0.002016 * n7 * (1.0 - g));
    return clamp(g, 0.0, 1.0);
}

vec3 saida3(vec2 uv) {
    vec3 lin = paraLuz(texture(g3, uv).rgb);
    vec3 luz = uGlow * (vec3(0.007268, 0.000000, 0.000000) * nivelF3_luz(0.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.000770, 0.008810) * nivelF3_luz(2.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.003105, 0.000424) * nivelF3_luz(4.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.000000, 0.002765) * nivelF3_luz(5.0 + 1.0 + acDeltaNivel(), uv));
    lin += luz * (1.0 - lin);
    return paraTela(lin);
}

vec3 nivelF5_luz(float n, vec2 uv) {
    n = clamp(n, 1.0, 8.0);
    float a = floor(n);
    float t = n - a;
    vec3 r = vec3(0.0);
    if (a == 1.0) r = abrir(lerLiso(f5_1, uv)) * (1.0 - t) + abrir(lerLiso(f5_2, uv)) * t;
    if (a == 2.0) r = abrir(lerLiso(f5_2, uv)) * (1.0 - t) + abrir(lerLiso(f5_3, uv)) * t;
    if (a == 3.0) r = abrir(lerLiso(f5_3, uv)) * (1.0 - t) + abrir(lerLiso(f5_4, uv)) * t;
    if (a == 4.0) r = abrir(lerLiso(f5_4, uv)) * (1.0 - t) + abrir(lerLiso(f5_5, uv)) * t;
    if (a == 5.0) r = abrir(lerLiso(f5_5, uv)) * (1.0 - t) + abrir(lerLiso(f5_6, uv)) * t;
    if (a == 6.0) r = abrir(lerLiso(f5_6, uv)) * (1.0 - t) + abrir(lerLiso(f5_7, uv)) * t;
    if (a == 7.0) r = abrir(lerLiso(f5_7, uv)) * (1.0 - t) + abrir(lerLiso(f5_8, uv)) * t;
    if (a == 8.0) r = abrir(lerLiso(f5_8, uv)) * (1.0 - t);
    return r;
}

vec3 popDe5(vec2 uv) {
    vec3 x = texture(x5, uv).rgb;
    vec3 g = x;
    return clamp(g, 0.0, 1.0);
}

vec3 saida5(vec2 uv) {
    vec3 lin = paraLuz(texture(g5, uv).rgb);
    vec3 luz = uGlow * (vec3(0.093060, 0.095552, 0.235638) * nivelF5_luz(0.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.133189, 0.200121, 0.039201) * nivelF5_luz(1.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.297974, 0.264439, 0.149420) * nivelF5_luz(2.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.000000, 0.021793, 0.000000) * nivelF5_luz(4.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.363954, 0.359585, 0.366160) * nivelF5_luz(5.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.038759, 0.071159, 0.021058) * nivelF5_luz(6.0 + 1.0 + acDeltaNivel(), uv) + vec3(0.038073, 0.000000, 0.106629) * nivelF5_luz(7.0 + 1.0 + acDeltaNivel(), uv));
    lin += luz * (1.0 - lin);
    return paraTela(lin);
}

vec3 antes2(vec2 uv) {
    vec3 c = clamp(texture(inputImg, uv).rgb, 0.0, 1.0);
    c = lut(c, 0.0);
    c = paraTela(clamp(paraLuz(c) * (texture(atlas, vec2((0.0 + clamp(uv.x * 64.0, 0.5, 64.0 - 0.5)) / 1089.0, (33.0 + clamp(uv.y * 36.0, 0.5, 36.0 - 0.5)) / 147.0)).rgb * 4.0), 0.0, 1.0));
    return c;
}

vec3 antes3(vec2 uv) {
    vec3 c = saida2(uv);
    return c;
}

vec3 antes5(vec2 uv) {
    vec3 c = saida3(uv);
    c = lut(c, 78.0);
    return c;
}

vec3 fim(vec2 uv) {
    vec3 c = saida5(uv);
    c = clamp(c * (texture(atlas, vec2((0.0 + clamp(uv.x * 64.0, 0.5, 64.0 - 0.5)) / 1089.0, (111.0 + clamp(uv.y * 36.0, 0.5, 36.0 - 0.5)) / 147.0)).rgb * 2.0) + (texture(atlas, vec2((64.0 + clamp(uv.x * 64.0, 0.5, 64.0 - 0.5)) / 1089.0, (111.0 + clamp(uv.y * 36.0, 0.5, 36.0 - 0.5)) / 147.0)).rgb - 0.5), 0.0, 1.0);
    return c;
}

void main() {
    if (acPass == 0) { fragColor = vec4(antes2(acScreenNorm), 1.0); return; }
    if (acPass == 1) { fragColor = vec4(descer(x2), 1.0); return; }
    if (acPass == 2) { fragColor = vec4(descer(x2_1), 1.0); return; }
    if (acPass == 3) { fragColor = vec4(descer(x2_2), 1.0); return; }
    if (acPass == 4) { fragColor = vec4(descer(x2_3), 1.0); return; }
    if (acPass == 5) { fragColor = vec4(descer(x2_4), 1.0); return; }
    if (acPass == 6) { fragColor = vec4(descer(x2_5), 1.0); return; }
    if (acPass == 7) { fragColor = vec4(descer(x2_6), 1.0); return; }
    if (acPass == 8) { fragColor = vec4(descer(x2_7), 1.0); return; }
    if (acPass == 9) { fragColor = vec4(popDe2(acScreenNorm), 1.0); return; }
    if (acPass == 10) { fragColor = descerComCorte(g2, 0.000000, 0.150000); return; }
    if (acPass == 11) { fragColor = descerLuz(f2_1); return; }
    if (acPass == 12) { fragColor = descerLuz(f2_2); return; }
    if (acPass == 13) { fragColor = descerLuz(f2_3); return; }
    if (acPass == 14) { fragColor = descerLuz(f2_4); return; }
    if (acPass == 15) { fragColor = descerLuz(f2_5); return; }
    if (acPass == 16) { fragColor = descerLuz(f2_6); return; }
    if (acPass == 17) { fragColor = descerLuz(f2_7); return; }
    if (acPass == 18) { fragColor = vec4(antes3(acScreenNorm), 1.0); return; }
    if (acPass == 19) { fragColor = vec4(descer(x3), 1.0); return; }
    if (acPass == 20) { fragColor = vec4(descer(x3_1), 1.0); return; }
    if (acPass == 21) { fragColor = vec4(descer(x3_2), 1.0); return; }
    if (acPass == 22) { fragColor = vec4(descer(x3_3), 1.0); return; }
    if (acPass == 23) { fragColor = vec4(descer(x3_4), 1.0); return; }
    if (acPass == 24) { fragColor = vec4(descer(x3_5), 1.0); return; }
    if (acPass == 25) { fragColor = vec4(descer(x3_6), 1.0); return; }
    if (acPass == 26) { fragColor = vec4(descer(x3_7), 1.0); return; }
    if (acPass == 27) { fragColor = vec4(popDe3(acScreenNorm), 1.0); return; }
    if (acPass == 28) { fragColor = descerComCorte(g3, 0.000000, 0.150000); return; }
    if (acPass == 29) { fragColor = descerLuz(f3_1); return; }
    if (acPass == 30) { fragColor = descerLuz(f3_2); return; }
    if (acPass == 31) { fragColor = descerLuz(f3_3); return; }
    if (acPass == 32) { fragColor = descerLuz(f3_4); return; }
    if (acPass == 33) { fragColor = descerLuz(f3_5); return; }
    if (acPass == 34) { fragColor = descerLuz(f3_6); return; }
    if (acPass == 35) { fragColor = descerLuz(f3_7); return; }
    if (acPass == 36) { fragColor = vec4(antes5(acScreenNorm), 1.0); return; }
    if (acPass == 37) { fragColor = vec4(popDe5(acScreenNorm), 1.0); return; }
    if (acPass == 38) { fragColor = descerComCorte(g5, 0.000000, 0.150000); return; }
    if (acPass == 39) { fragColor = descerLuz(f5_1); return; }
    if (acPass == 40) { fragColor = descerLuz(f5_2); return; }
    if (acPass == 41) { fragColor = descerLuz(f5_3); return; }
    if (acPass == 42) { fragColor = descerLuz(f5_4); return; }
    if (acPass == 43) { fragColor = descerLuz(f5_5); return; }
    if (acPass == 44) { fragColor = descerLuz(f5_6); return; }
    if (acPass == 45) { fragColor = descerLuz(f5_7); return; }
    vec4 base = texture(inputImg, acScreenNorm);
    fragColor = vec4(mix(base.rgb, fim(acScreenNorm), uIntensidade), base.a);
}
